import java.util.*;
import java.io.*;

public class Main {
    public static List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> res = new ArrayList<>();
        if (matrix.length == 0) return res;
        int top = 0, bottom = matrix.length - 1;
        int left = 0, right = matrix[0].length - 1;
        while (top <= bottom && left <= right) {
            for (int i = left; i <= right; i++) res.add(matrix[top][i]);
            top++;
            for (int i = top; i <= bottom; i++) res.add(matrix[i][right]);
            right--;
            if (top <= bottom) {
                for (int i = right; i >= left; i--) res.add(matrix[bottom][i]);
                bottom--;
            }
            if (left <= right) {
                for (int i = bottom; i >= top; i--) res.add(matrix[i][left]);
                left++;
            }
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line; while((line = br.readLine()) != null) sb.append(line);
        String s = sb.toString().trim();
        if (s.isEmpty()) return;
        s = s.substring(1, s.length()-1); // remove outer []
        List<int[]> rows = new ArrayList<>();
        int i = 0;
        while(i < s.length()) {
            if(s.charAt(i) == '[') {
                int j = i + 1;
                while(j < s.length() && s.charAt(j) != ']') j++;
                String rowStr = s.substring(i+1, j).replace(",", " ").trim();
                if(!rowStr.isEmpty()) {
                    String[] parts = rowStr.split("\\s+");
                    int[] row = new int[parts.length];
                    for(int k=0; k<parts.length; k++) row[k] = Integer.parseInt(parts[k]);
                    rows.add(row);
                }
                i = j + 1;
            } else i++;
        }
        int[][] matrix = rows.toArray(new int[0][]);
        System.out.println(spiralOrder(matrix).toString().replace(" ", ""));
    }
}

